import 'package:flutter/material.dart';\r\nimport '../../core/theme/app_colors.dart';\r\nimport 'staff_dashboard_screen.dart';\r\nimport 'customer_search_screen.dart';\r\nimport 'branch_appointments_screen.dart';\r\n\r\n/// Main scaffold for the staff role with bottom navigation.\r\n///\r\n/// Tabs: Dashboard, Appointments, Customer Search\r\n/// Per PRD §5.2 — the staff operational experience.\r\nclass StaffMainScaffold extends StatefulWidget {\r\n  const StaffMainScaffold({super.key});\r\n\r\n  @override\r\n  State<StaffMainScaffold> createState() => _StaffMainScaffoldState();\r\n}\r\n\r\nclass _StaffMainScaffoldState extends State<StaffMainScaffold> {\r\n  int _currentIndex = 0;\r\n\r\n  final List<Widget> _pages = const [\r\n    StaffDashboardScreen(),\r\n    BranchAppointmentsScreen(),\r\n    CustomerSearchScreen(),\r\n  ];\r\n\r\n  @override\r\n  Widget build(BuildContext context) {\r\n    return Scaffold(\r\n      body: IndexedStack(\r\n        index: _currentIndex,\r\n        children: _pages,\r\n      ),\r\n      bottomNavigationBar: NavigationBar(\r\n        selectedIndex: _currentIndex,\r\n        onDestinationSelected: (index) {\r\n          setState(() => _currentIndex = index);\r\n        },\r\n        destinations: const [\r\n          NavigationDestination(\r\n            icon: Icon(Icons.dashboard_outlined),\r\n            selectedIcon: Icon(Icons.dashboard),\r\n            label: 'Dashboard',\r\n          ),\r\n          NavigationDestination(\r\n            icon: Icon(Icons.calendar_month_outlined),\r\n            selectedIcon: Icon(Icons.calendar_month),\r\n            label: 'Appointments',\r\n          ),\r\n          NavigationDestination(\r\n            icon: Icon(Icons.search),\r\n            selectedIcon: Icon(Icons.person_search),\r\n            label: 'Customers',\r\n          ),\r\n        ],\r\n      ),\r\n    );\r\n  }\r\n}\r\n
